#include <iostream>
#include <vector>

struct Recuento {
    int aceptados;
    int rechazados;
};

bool recuento_valido(const Recuento& valor) {
    return valor.aceptados >= 0 && valor.aceptados <= 10
        && valor.rechazados >= 0 && valor.rechazados <= 10;
}

struct Registro {
    int id;
    Recuento recuento;
};

struct Celda {
    bool presente;
    Recuento recuento;
};

bool insertar(std::vector<Celda>& tabla, const Registro& registro) {
    if (tabla.size() != 10 || registro.id < 0 || registro.id > 9
        || !recuento_valido(registro.recuento)) {
        return false;
    }
    Celda& celda = tabla.at(registro.id);
    if (celda.presente) {
        return false;
    }
    celda = Celda{true, registro.recuento};
    return true;
}

bool consultar(const std::vector<Celda>& tabla, int id, Recuento& destino) {
    if (tabla.size() != 10 || id < 0 || id > 9) {
        return false;
    }
    const Celda& celda = tabla.at(id);
    if (!celda.presente) {
        return false;
    }
    destino = celda.recuento;
    return true;
}

int main() {
    std::vector<Celda> tabla(10, Celda{false, {0, 0}});
    bool primero = insertar(tabla, Registro{7, {0, 0}});
    bool repetido = insertar(tabla, Registro{7, {1, 1}});
    bool fuera = insertar(tabla, Registro{10, {1, 1}});
    std::cout << primero << ':' << repetido << ':' << fuera << '\n';
    Recuento resultado{9, 9};
    bool encontrado = consultar(tabla, 7, resultado);
    std::cout << encontrado << ':' << resultado.aceptados
              << ':' << resultado.rechazados << '\n';
    resultado = Recuento{9, 9};
    bool ausente = consultar(tabla, 3, resultado);
    std::cout << ausente << ':' << resultado.aceptados
              << ':' << resultado.rechazados;
    return 0;
}

